import {existsSync} from 'node:fs';
import {join} from 'node:path';
import type {Photo} from './model';
import {path} from './paths';

export interface ResponsiveImage {src: string; width: number; height: number; srcset?: string; avif?: string;}

// AVIF siblings are generated by scripts/build-avif.mjs. A source is only emitted when every
// width exists, so a partial set never sends the browser to a missing file.
export function responsive(photo: Photo | undefined | null): ResponsiveImage | null {
  if (!photo || photo.status !== 'ready' || !photo.path || !photo.width || !photo.height) return null;
  const candidates = [...photo.variants.map(v => ({width: v.width, file: v.path})), {width: photo.width, file: photo.path}]
    .filter((c, i, all) => c.width <= photo.width! && all.findIndex(x => x.width === c.width) === i)
    .sort((a, b) => a.width - b.width);
  const stem = photo.path.replace(/\.[a-z0-9]+$/i, '');
  const avifFiles = candidates.map(c => ({width: c.width, file: `${stem}-${c.width}.avif`}));
  const hasAvif = avifFiles.every(f => existsSync(join(process.cwd(), 'public', f.file)));
  return {
    src: path(photo.path),
    width: photo.width,
    height: photo.height,
    srcset: candidates.length > 1 ? candidates.map(c => `${path(c.file)} ${c.width}w`).join(', ') : undefined,
    avif: hasAvif ? avifFiles.map(f => `${path(f.file)} ${f.width}w`).join(', ') : undefined,
  };
}
